// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.calendar/** * NOUS — Calendar Data Models (Module 14 v1.2 — Step 14.4). * * Data structures for calendar events + reminders. * * ## Real Android APIs Used (transitively via Reader/Writer) * * | Operation | API | * |-----------|-----| * | Event insert | `ContentResolver.insert(CalendarContract.Events.CONTENT_URI, ...)` | * | Event query  | `ContentResolver.query(CalendarContract.Events.CONTENT_URI, ...)` | * | Event update | `ContentResolver.update(...)` | * | Event delete | `ContentResolver.delete(...)` | * | Reminder insert | `ContentResolver.insert(CalendarContract.Reminders.CONTENT_URI, ...)` | * | Reminder query  | `ContentResolver.query(CalendarContract.Reminders.CONTENT_URI, ...)` | * * ## Privacy * * Calendar data is NOT encrypted — it lives in the system Calendar provider * (shared with other apps that have READ_CALENDAR permission). NOUS never * copies calendar data into its own DB; all operations go through the system * provider at call time. The user's calendar content stays where it belongs. *//** * A calendar event (REAL CalendarContract.Events row). * * @property id             event ID (from CalendarContract.Events._ID). * @property title          event title. * @property startMs        start time (epoch ms). * @property endMs          end time (epoch ms). * @property location       optional location string. * @property description    optional description. * @property calendarId     ID of the calendar this event belongs to. * @property isAllDay       true if this is an all-day event. * @property hasAlarm       true if the event has at least one reminder. * @property reminders      list of reminders set on this event. */data class CalendarEvent(    val id: Long,    val title: String,    val startMs: Long,    val endMs: Long,    val location: String? = null,    val description: String? = null,    val calendarId: Long = PRIMARY_CALENDAR_ID_PLACEHOLDER,    val isAllDay: Boolean = false,    val hasAlarm: Boolean = false,    val reminders: List<CalendarReminder> = emptyList(),) {    /** Duration in milliseconds (end - start). */    val durationMs: Long get() = (endMs - startMs).coerceAtLeast(0)    /** Duration in minutes (rounded down). */    val durationMinutes: Long get() = durationMs / 60_000    /** Human-readable start time (e.g., "3:00 PM, Mon"). */    val displayStartTime: String        get() {            val sdf = java.text.SimpleDateFormat("h:mm a, EEE", java.util.Locale.getDefault())            return sdf.format(java.util.Date(startMs))        }    /** True if the event is currently in progress (now is between start + end). */    fun isInProgress(now: Long = System.currentTimeMillis()): Boolean =        now in startMs..endMs    /** True if the event has already ended. */    fun hasEnded(now: Long = System.currentTimeMillis()): Boolean = now > endMs    /** True if the event is in the future. */    fun isUpcoming(now: Long = System.currentTimeMillis()): Boolean = now < startMs    companion object {        /** Placeholder used when calendar ID is unknown (will be resolved at insert time). */        const val PRIMARY_CALENDAR_ID_PLACEHOLDER: Long = -1L    }}/** * A reminder attached to a calendar event (REAL CalendarContract.Reminders row). * * @property eventId           the event this reminder belongs to. * @property minutesBefore     how many minutes before the event the reminder fires. * @property method            reminder method (see [ReminderMethod]). */data class CalendarReminder(    val eventId: Long,    val minutesBefore: Int,    val method: Int = ReminderMethod.ALERT.value,)/** * Reminder delivery method (per CalendarContract.Reminders.METHOD_* constants). * * @see <a href="https://developer.android.com/reference/android/provider/CalendarContract.Reminders#METHOD_ALERT">CalendarContract.Reminders.METHOD_ALERT</a> */enum class ReminderMethod(val value: Int, val displayName: String) {    /** Default — uses the device's default alert (sound + vibration). */    ALERT(1, "Alert"),    /** Email reminder (sent by calendar sync backend). */    EMAIL(2, "Email"),    /** SMS reminder (sent by calendar sync backend). */    SMS(3, "SMS"),    /** System reserved. */    DEFAULT(0, "Default");    companion object {        /** Convert an int value to a [ReminderMethod] (defaults to ALERT for unknown values). */        fun fromValue(value: Int): ReminderMethod =            entries.firstOrNull { it.value == value } ?: ALERT    }}/** * Result of calendar operations (sealed class for async returns). * * Mirrors [com.roshan.persona.productivity.alarm.AlarmResult] + * [com.roshan.persona.productivity.reminder.ReminderResult] + * [com.roshan.persona.productivity.note.NoteResult] for consistency. */sealed interface CalendarResult<out T> {    data class Success<T>(val data: T, val spokenMessage: String) : CalendarResult<T>    data class Failure(val error: String, val spokenMessage: String) : CalendarResult<Nothing>    data class NeedsPermission(val permissions: List<String>, val spokenMessage: String) : CalendarResult<Nothing>}// ═══════════════════════════════════════════════════════════════════════════// Calendar Store (in-memory cache for unit tests — production reads from// CalendarContract.Events via ContentResolver directly)// ═══════════════════════════════════════════════════════════════════════════/** * Calendar Store — in-memory cache for unit tests. * * Production: [CalendarEngine] reads/writes via [CalendarReader] / * [CalendarWriter] (ContentResolver). This in-memory store mirrors the * same interface so unit tests can exercise [CalendarEngine] without * a real ContentResolver. */class CalendarStore {    private val events = mutableMapOf<Long, CalendarEvent>()    private val reminders = mutableMapOf<Long, MutableList<CalendarReminder>>()    /** Insert or replace an event. */    fun putEvent(event: CalendarEvent) {        events[event.id] = event    }    /** Get an event by ID. */    fun getEventById(id: Long): CalendarEvent? = events[id]    /** Get all events. */    fun getAllEvents(): List<CalendarEvent> = events.values.sortedBy { it.startMs }    /** Get upcoming events (start time > now). */    fun getUpcomingEvents(now: Long = System.currentTimeMillis()): List<CalendarEvent> =        events.values.filter { it.startMs > now }.sortedBy { it.startMs }    /** Get the next upcoming event (earliest start time after now). */    fun getNextEvent(now: Long = System.currentTimeMillis()): CalendarEvent? =        getUpcomingEvents(now).firstOrNull()    /** Get events in a time range [startMs, endMs]. */    fun getEventsInRange(startMs: Long, endMs: Long): List<CalendarEvent> =        events.values            .filter { it.startMs in startMs..endMs || it.endMs in startMs..endMs ||                      (it.startMs <= startMs && it.endMs >= endMs) }            .sortedBy { it.startMs }    /** Get today's events (start of today → end of today). */    fun getTodayEvents(now: Long = System.currentTimeMillis()): List<CalendarEvent> {        val cal = java.util.Calendar.getInstance().apply { timeInMillis = now }        cal.set(java.util.Calendar.HOUR_OF_DAY, 0)        cal.set(java.util.Calendar.MINUTE, 0)        cal.set(java.util.Calendar.SECOND, 0)        cal.set(java.util.Calendar.MILLISECOND, 0)        val startOfDay = cal.timeInMillis        cal.add(java.util.Calendar.DAY_OF_MONTH, 1)        val endOfDay = cal.timeInMillis - 1        return getEventsInRange(startOfDay, endOfDay)    }    /** Delete an event by ID. */    fun deleteEvent(id: Long): Boolean {        reminders.remove(id)        return events.remove(id) != null    }    /** Add a reminder to an event. */    fun addReminder(reminder: CalendarReminder) {        reminders.getOrPut(reminder.eventId) { mutableListOf() }.add(reminder)    }    /** Get reminders for an event. */    fun getReminders(eventId: Long): List<CalendarReminder> =        reminders[eventId]?.toList() ?: emptyList()    /** Clear all events + reminders (used by tests). */    fun clear() {        events.clear()        reminders.clear()    }    /** Event count. */    fun count(): Int = events.size}